-- Run once (seed_runs). Puducherry Tier A leaders, generated by scraper/src/bihar/leaders-cli.ts from the curated
-- scraper/data/py/leaders.json and leader-profiles.json: candidacy links (never moving curated or merged
-- persons), fill-only profile fields, and the leaders/cabinet watchlists of each Puducherry manifest (written once;
-- admins edit them afterwards). Persons and image credits above the guard are idempotent and run every time.
SELECT NOT EXISTS (SELECT 1 FROM seed_runs WHERE name = 'seed_py_leaders')
   AS seed_apply \gset
\if :seed_apply

-- Link each leader's candidacies to the best-linked person. A candidacy moves from a one-candidacy person or from a
-- person whose candidacies all belong to this leader (leaders.json is curated); never from a merge, a split or a
-- person with an admin-entered profile.
UPDATE candidates c SET person_id = (SELECT c.person_id FROM candidates c WHERE c.id IN ('2900ae44-2cf0-544b-b6f1-3030cfaf3e53', 'f7330cfc-89d2-5016-bfa7-e5ce1023d8af') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1)
WHERE c.id IN ('2900ae44-2cf0-544b-b6f1-3030cfaf3e53', 'f7330cfc-89d2-5016-bfa7-e5ce1023d8af') AND c.person_id <> (SELECT c.person_id FROM candidates c WHERE c.id IN ('2900ae44-2cf0-544b-b6f1-3030cfaf3e53', 'f7330cfc-89d2-5016-bfa7-e5ce1023d8af') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1)
  AND ((SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) = 1
       OR NOT EXISTS (SELECT 1 FROM candidates c3 WHERE c3.person_id = c.person_id AND c3.id NOT IN ('2900ae44-2cf0-544b-b6f1-3030cfaf3e53', 'f7330cfc-89d2-5016-bfa7-e5ce1023d8af')))
  AND NOT EXISTS (SELECT 1 FROM person_merges pm WHERE pm.duplicate->>'id' = c.person_id::text OR pm.keeper_ref = c.person_id)
  AND NOT EXISTS (SELECT 1 FROM audit_logs al WHERE al.action = 'CANDIDATE_SPLIT' AND al.entity_type = 'candidate' AND al.entity_id = c.id::text)
  AND NOT EXISTS (SELECT 1 FROM persons pp WHERE pp.id = c.person_id AND (pp.photo_url IS NOT NULL OR pp.bio IS NOT NULL OR pp.wikipedia_url IS NOT NULL OR pp.date_of_birth IS NOT NULL));

-- Profiles, fill-only (admin edits win)
UPDATE persons SET photo_url = COALESCE(photo_url, 'https://ont9tlwrlxhj4iwf.public.blob.vercel-storage.com/persons/Q599267/photo.jpg'), date_of_birth = COALESCE(date_of_birth, '1950-08-04'::date), gender = COALESCE(gender, 'M'), wikipedia_url = COALESCE(wikipedia_url, 'https://en.wikipedia.org/wiki/N._Rangaswamy'), bio = COALESCE(bio, 'Chief Minister of Puducherry in the 2026 government.'), state_id = COALESCE(state_id, 27) WHERE id = (SELECT c.person_id FROM candidates c WHERE c.id IN ('2900ae44-2cf0-544b-b6f1-3030cfaf3e53', 'f7330cfc-89d2-5016-bfa7-e5ce1023d8af') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1);
UPDATE persons SET gender = COALESCE(gender, 'M'), wikipedia_url = COALESCE(wikipedia_url, 'https://en.wikipedia.org/wiki/A._M._H._Nazeem'), bio = COALESCE(bio, 'Leader of the Opposition after the 2026 election.'), state_id = COALESCE(state_id, 27) WHERE id = (SELECT c.person_id FROM candidates c WHERE c.id IN ('63dd8ac0-7b24-591e-ac73-d5fbee9a12df') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1);
UPDATE persons SET date_of_birth = COALESCE(date_of_birth, '1967-01-01'::date), gender = COALESCE(gender, 'M'), wikipedia_url = COALESCE(wikipedia_url, 'https://en.wikipedia.org/wiki/R._Siva'), bio = COALESCE(bio, 'Outgoing Leader of the Opposition, candidate in the 2026 election.'), state_id = COALESCE(state_id, 27) WHERE id = (SELECT c.person_id FROM candidates c WHERE c.id IN ('df2d8a55-32a0-5376-8385-53f15b985a35') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1);
UPDATE persons SET photo_url = COALESCE(photo_url, 'https://ont9tlwrlxhj4iwf.public.blob.vercel-storage.com/persons/Q7906295/photo.jpg'), date_of_birth = COALESCE(date_of_birth, '1950-10-05'::date), gender = COALESCE(gender, 'M'), wikipedia_url = COALESCE(wikipedia_url, 'https://en.wikipedia.org/wiki/V._Vaithilingam'), bio = COALESCE(bio, 'Congress candidate against the Chief Minister in the 2026 election.'), state_id = COALESCE(state_id, 27) WHERE id = (SELECT c.person_id FROM candidates c WHERE c.id IN ('aebb896c-b194-59e7-bf0f-d20f62784107') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1);
UPDATE persons SET photo_url = COALESCE(photo_url, 'https://ont9tlwrlxhj4iwf.public.blob.vercel-storage.com/persons/Q105452337/photo.png'), gender = COALESCE(gender, 'M'), wikipedia_url = COALESCE(wikipedia_url, 'https://en.wikipedia.org/wiki/A._Namassivayam'), bio = COALESCE(bio, 'Minister of Home, Education and Electricity in the 2026 government.'), state_id = COALESCE(state_id, 27) WHERE id = (SELECT c.person_id FROM candidates c WHERE c.id IN ('b9137a24-d1b2-5c32-8ba5-58c60bfd8003') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1);
UPDATE persons SET photo_url = COALESCE(photo_url, 'https://ont9tlwrlxhj4iwf.public.blob.vercel-storage.com/persons/Q21064273/photo.jpg'), date_of_birth = COALESCE(date_of_birth, '1964-06-06'::date), gender = COALESCE(gender, 'M'), wikipedia_url = COALESCE(wikipedia_url, 'https://en.wikipedia.org/wiki/Malladi_Krishna_Rao'), bio = COALESCE(bio, 'Minister of Public Works, Tourism and Industries in the 2026 government.'), state_id = COALESCE(state_id, 27) WHERE id = (SELECT c.person_id FROM candidates c WHERE c.id IN ('7a5857c3-a256-5ce2-9be8-cb695a87a261') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1);
UPDATE persons SET gender = COALESCE(gender, 'M'), wikipedia_url = COALESCE(wikipedia_url, 'https://en.wikipedia.org/wiki/P._Rajavelu'), bio = COALESCE(bio, 'Minister of Adi Dravidar Welfare, Housing and Information Technology in the 2026 government.'), state_id = COALESCE(state_id, 27) WHERE id = (SELECT c.person_id FROM candidates c WHERE c.id IN ('dbd460f7-4cce-5845-aa6a-9fddda865cce') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1);
UPDATE persons SET gender = COALESCE(gender, 'M'), wikipedia_url = COALESCE(wikipedia_url, 'https://en.wikipedia.org/wiki/V._P._Sivakolundhu'), bio = COALESCE(bio, 'Minister of Civil Supplies and Social Welfare in the 2026 government.'), state_id = COALESCE(state_id, 27) WHERE id = (SELECT c.person_id FROM candidates c WHERE c.id IN ('4ca4c203-5ae3-5bc5-af0d-571f7ca46f64') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1);
UPDATE persons SET gender = COALESCE(gender, 'M'), wikipedia_url = COALESCE(wikipedia_url, 'https://en.wikipedia.org/wiki/G._N._S._Rajasekaran'), bio = COALESCE(bio, 'Minister of Agriculture, Rural Development and Sports in the 2026 government.'), state_id = COALESCE(state_id, 27) WHERE id = (SELECT c.person_id FROM candidates c WHERE c.id IN ('1d413911-7c80-513b-8720-8b4fb9de9552') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1);

-- Manifests: leaders and cabinet watchlists by person_id
UPDATE elections SET manifest_url = (manifest_url::jsonb || jsonb_build_object('watchlists', jsonb_build_array(
  jsonb_build_object('id', 'leaders', 'name', 'Leaders', 'entries', jsonb_build_array(
    jsonb_build_object('name', 'N. Rangasamy', 'party_id', 'AINRC', 'const_id', 'PY_VS26_4_MANGALAM', 'role', 'Chief Minister', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('2900ae44-2cf0-544b-b6f1-3030cfaf3e53', 'f7330cfc-89d2-5016-bfa7-e5ce1023d8af') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text),
    jsonb_build_object('name', 'A. M. H. Nazeem', 'party_id', 'DMK', 'const_id', 'PY_VS26_27_KARAIKAL_SOUTH', 'role', 'Leader of the Opposition', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('63dd8ac0-7b24-591e-ac73-d5fbee9a12df') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text),
    jsonb_build_object('name', 'R. Siva', 'party_id', 'DMK', 'const_id', 'PY_VS26_5_VILLIANUR', 'role', 'Outgoing Leader of the Opposition, candidate', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('df2d8a55-32a0-5376-8385-53f15b985a35') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text),
    jsonb_build_object('name', 'V. Vaithilingam', 'party_id', 'INC', 'const_id', 'PY_VS26_9_THATTANCHAVADY', 'role', 'Congress candidate against the Chief Minister', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('aebb896c-b194-59e7-bf0f-d20f62784107') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text))),
  jsonb_build_object('id', 'cabinet', 'name', 'Cabinet', 'entries', jsonb_build_array(
    jsonb_build_object('name', 'A. Namassivayam', 'party_id', 'BJP', 'const_id', 'PY_VS26_1_MANNADIPET', 'role', 'Minister of Home, Education and Electricity', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('b9137a24-d1b2-5c32-8ba5-58c60bfd8003') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text),
    jsonb_build_object('name', 'Malladi Krishna Rao', 'party_id', 'AINRC', 'const_id', 'PY_VS26_30_YANAM', 'role', 'Minister of Public Works, Tourism and Industries', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('7a5857c3-a256-5ce2-9be8-cb695a87a261') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text),
    jsonb_build_object('name', 'P. Rajavelu', 'party_id', 'AINRC', 'const_id', 'PY_VS26_22_NETTAPAKKAM', 'role', 'Minister of Adi Dravidar Welfare, Housing and Information Technology', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('dbd460f7-4cce-5845-aa6a-9fddda865cce') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text),
    jsonb_build_object('name', 'V. P. Sivakolundhu', 'party_id', 'AINRC', 'const_id', 'PY_VS26_11_LAWSPET', 'role', 'Minister of Civil Supplies and Social Welfare', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('4ca4c203-5ae3-5bc5-af0d-571f7ca46f64') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text),
    jsonb_build_object('name', 'G. N. S. Rajasekaran', 'party_id', 'BJP', 'const_id', 'PY_VS26_25_THIRUNALLAR', 'role', 'Minister of Agriculture, Rural Development and Sports', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('1d413911-7c80-513b-8720-8b4fb9de9552') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text))))))::text
WHERE id = 'b1c2d3e4-f5a6-7890-1234-567890ab2026' AND manifest_url LIKE '{%' AND CASE WHEN manifest_url LIKE '{%' THEN NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(manifest_url::jsonb->'watchlists', '[]'::jsonb)) w WHERE jsonb_array_length(COALESCE(w->'entries', '[]'::jsonb)) > 0) ELSE false END;
UPDATE elections SET manifest_draft = manifest_draft || jsonb_build_object('watchlists', jsonb_build_array(
  jsonb_build_object('id', 'leaders', 'name', 'Leaders', 'entries', jsonb_build_array(
    jsonb_build_object('name', 'N. Rangasamy', 'party_id', 'AINRC', 'const_id', 'PY_VS26_4_MANGALAM', 'role', 'Chief Minister', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('2900ae44-2cf0-544b-b6f1-3030cfaf3e53', 'f7330cfc-89d2-5016-bfa7-e5ce1023d8af') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text),
    jsonb_build_object('name', 'A. M. H. Nazeem', 'party_id', 'DMK', 'const_id', 'PY_VS26_27_KARAIKAL_SOUTH', 'role', 'Leader of the Opposition', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('63dd8ac0-7b24-591e-ac73-d5fbee9a12df') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text),
    jsonb_build_object('name', 'R. Siva', 'party_id', 'DMK', 'const_id', 'PY_VS26_5_VILLIANUR', 'role', 'Outgoing Leader of the Opposition, candidate', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('df2d8a55-32a0-5376-8385-53f15b985a35') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text),
    jsonb_build_object('name', 'V. Vaithilingam', 'party_id', 'INC', 'const_id', 'PY_VS26_9_THATTANCHAVADY', 'role', 'Congress candidate against the Chief Minister', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('aebb896c-b194-59e7-bf0f-d20f62784107') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text))),
  jsonb_build_object('id', 'cabinet', 'name', 'Cabinet', 'entries', jsonb_build_array(
    jsonb_build_object('name', 'A. Namassivayam', 'party_id', 'BJP', 'const_id', 'PY_VS26_1_MANNADIPET', 'role', 'Minister of Home, Education and Electricity', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('b9137a24-d1b2-5c32-8ba5-58c60bfd8003') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text),
    jsonb_build_object('name', 'Malladi Krishna Rao', 'party_id', 'AINRC', 'const_id', 'PY_VS26_30_YANAM', 'role', 'Minister of Public Works, Tourism and Industries', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('7a5857c3-a256-5ce2-9be8-cb695a87a261') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text),
    jsonb_build_object('name', 'P. Rajavelu', 'party_id', 'AINRC', 'const_id', 'PY_VS26_22_NETTAPAKKAM', 'role', 'Minister of Adi Dravidar Welfare, Housing and Information Technology', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('dbd460f7-4cce-5845-aa6a-9fddda865cce') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text),
    jsonb_build_object('name', 'V. P. Sivakolundhu', 'party_id', 'AINRC', 'const_id', 'PY_VS26_11_LAWSPET', 'role', 'Minister of Civil Supplies and Social Welfare', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('4ca4c203-5ae3-5bc5-af0d-571f7ca46f64') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text),
    jsonb_build_object('name', 'G. N. S. Rajasekaran', 'party_id', 'BJP', 'const_id', 'PY_VS26_25_THIRUNALLAR', 'role', 'Minister of Agriculture, Rural Development and Sports', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('1d413911-7c80-513b-8720-8b4fb9de9552') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text)))))
WHERE id = 'b1c2d3e4-f5a6-7890-1234-567890ab2026' AND jsonb_typeof(manifest_draft) = 'object' AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(manifest_draft->'watchlists', '[]'::jsonb)) w WHERE jsonb_array_length(COALESCE(w->'entries', '[]'::jsonb)) > 0);

\endif
INSERT INTO seed_runs (name) VALUES ('seed_py_leaders') ON CONFLICT (name) DO NOTHING;

COMMIT;

